import json,csv,re
from pathlib import Path
D=Path('/workspace/scratch/aeb9afdc0c41/fragments/b')
talks=[];items=[];problems=[];corrections=[]
def save():
 def clean(obj):
  if isinstance(obj,str): return obj.replace("\\'s", "'s")
  if isinstance(obj,list): return [clean(x) for x in obj]
  if isinstance(obj,dict): return {k:clean(v) for k,v in obj.items()}
  return obj
 for name,obj in [('talks',talks),('items',items),('problems',problems)]:
  (D/(name+'.json')).write_text(json.dumps(clean(obj),ensure_ascii=False,indent=2)+'\n')
 with (D/'corrections.csv').open('w',newline='') as f:
  w=csv.writer(f);w.writerow(['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writerows(corrections)
def t(record,date,speaker,pages,title,summary,kind='talk'):
 talks.append(dict(record=record,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))
def i(rec,pages,kind,title,notes,statement,reconstruction='',cls='E',fate='',status='',literal='correct',match='exact',verification='read the result',development='annotated',problem='',worth='',refs=(),confidence='high',speaker=None):
 n=sum(x['record']==rec for x in items)+1
 y=1967 if rec<=147 else 1968
 o=dict(id=f'{y}-{rec}.{n}',record=rec,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status='As of November 2026, '+status,literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
 if speaker:o['speaker']=speaker
 items.append(o);return o['id']
def c(page,place,reads,should,evidence,applies='both',typ='faithful_error'):
 corrections.append([page,place,reads,should,evidence,applies,typ])
def p(pid,title,statement,occ,status,refs):
 problems.append(dict(id=pid,title=title,statement=statement,occurrences=occ,status=status,status_date='2026-11',refs=list(refs)))

